let prescriptionNo = extraData.prescriptionNo;
this.getFormRef().executeDataSource('getMedicationGuidanceInfo',{prescriptionNo:prescriptionNo}).then(res => {
    for(let item of mg_pre_select){
      let content = ''
      if(!Array.isArray(item.guidanceType)){
          content = GetContent(res,item.guidanceType)
      }else{
        debugger
        for(let guidanceType of item.guidanceType){
          content += GetContent(res,guidanceType)
        }
      }
      this.getWidgetRef(item.select,false).setValue(content);
    }

});


function GetContent(res,guidanceType){
  let data = res.filter(n=> n.guidanceType == guidanceType)
  if(data.length > 0){
    return data[0].content
  }
  return '';
}


