  async function LoadMedicationGuidance(that){
    let prescriptionJson = that.getWidgetRef('prescriptionJson').getValue();
    let prescriptionNo = that.getWidgetRef('prescriptionNo').getValue();
    let prescriptionId = that.getWidgetRef('preId').getValue();
    for(let item of mg_select){
       let select = that.getWidgetRef(item.select)
        select.setValue([]);
     }
     for(let item of mg_select){
        guidanceType = item.guidanceType
        if(!Array.isArray(item.guidanceType)){
          guidanceType = [item.guidanceType]
        }
        await HandleMedicationGuidance(prescriptionJson,prescriptionNo,prescriptionId,item,that);
        await wait(10);
     }

  }

  function HandleMedicationGuidance(prescriptionJson,prescriptionNo,prescriptionId,item,that){
      return new Promise((resolve, reject) => {
      that.getFormRef().executeDataSource(item.urlName,{select:item.select,guidanceType:guidanceType,prescriptionJson:prescriptionJson
          ,prescriptionNo:prescriptionNo,prescriptionId:prescriptionId
        }).then(res =>{
          let select = that.getWidgetRef(res.select)
          select.loadOptions(res.result)
          let defaultSelect = []
          if (res.result.length >0){
            for(let rule of res.result){
              if(rule.isSelect){
                defaultSelect.push(rule.key)
              }
            }
          }
          select.setValue(defaultSelect);

          resolve();

        });
      });
  }


function wait(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

